def from_Note(note):
    c = Composition()
    c.add_note(note)
    return _composition2musicxml(c).toprettyxml()

def from_Note(note, width=80, tuning=None):
    """Return a string made out of ASCII tablature representing a Note object
    or note string.

    Throw a RangeError if a suitable fret can't be found.

    'tuning' should be a StringTuning object or None for the default tuning.

    To force a certain fingering you can use a 'string' and 'fret' attribute
    on the Note. If the fingering is valid, it will get used instead of the
    default one.
    """
    if tuning is None:
        tuning = default_tuning
    result = begin_track(tuning)
    min = 1000
    (s, f) = (-1, -1)

    # Do an attribute check
    if hasattr(note, "string") and hasattr(note, "fret"):
        n = tuning.get_Note(note.string, note.fret)
        if n is not None and int(n) == int(note):
            (s, f) = (note.string, note.fret)
            min = 0

    if min == 1000:
        for (string, fret) in enumerate(tuning.find_frets(note)):
            if fret is not None:
                if fret < min:
                    min = fret
                    (s, f) = (string, fret)
    l = len(result[0])
    w = max(4, (width - l) - 1)

    # Build ASCII
    if min != 1000:
        fret = str(f)
        for i in range(len(result)):
            d = len(fret)
            if i != s:
                result[i] += "-" * w + "|"
            else:
                d = w - len(fret)
                result[i] += "-" * (d // 2) + fret
                d = (w - d // 2) - len(fret)
                result[i] += "-" * d + "|"
    else:
        raise RangeError(
            "No fret found that could play note '%s'. " "Note out of range." % note
        )
    result.reverse()
    return os.linesep.join(result)

def from_NoteContainer(nc, duration=None, standalone=True):
    """Get a NoteContainer object and return the LilyPond equivalent in a
    string.

    The second argument determining the duration of the NoteContainer is
    optional. When the standalone argument is True the result of this
    function can be used directly by functions like to_png. It is mostly
    here to be used by from_Bar.
    """
    # Throw exception
    if nc is not None and not hasattr(nc, "notes"):
        return False

    # Return rests for None or empty lists
    if nc is None or len(nc.notes) == 0:
        result = "r"
    elif len(nc.notes) == 1:

        # Return a single note if the list contains only one note
        result = from_Note(nc.notes[0], standalone=False)
    else:
        # Return the notes grouped in '<' and '>'
        result = "<"
        for notes in nc.notes:
            result += from_Note(notes, standalone=False) + " "
        result = result[:-1] + ">"

    # Add the duration
    if duration != None:
        parsed_value = value.determine(duration)

        # Special case: check for longa and breve in the duration (issue #37)
        dur = parsed_value[0]
        if dur == value.longa:
            result += "\\longa"
        elif dur == value.breve:
            result += "\\breve"
        else:
            result += str(int(parsed_value[0]))
        for i in range(parsed_value[1]):
            result += "."
    if not standalone:
        return result
    else:
        return "{ %s }" % result
